/**
 * Font Loading Service
 *
 * Provides font file buffers for SVG-to-PNG rendering with resvg-wasm.
 * Fonts are bundled directly into the Worker at build time by wrangler.
 *
 * Brand fonts:
 * - Space Grotesk: Headers (variable weight 300-700)
 * - Onest: Body text, labels (variable weight 100-900)
 * - Fragment Mono: Hex codes and numeric columns (5.0 — replaced Habibi,
 *   which was a proportional serif and never aligned numbers)
 *
 * CJK fonts (for Japanese/Korean/Chinese support) — three subsets, all
 * generated by scripts/subset-cjk-fonts.py from the codepoints present in the
 * core + bot-logic/i18n locale JSON files and api-worker's ko / zh / ja
 * item-name tables (FONT-001 — re-run it after any locale edit or item-table
 * rebuild):
 * - Noto Sans SC: the CJK catch-all, cut from every language's text (Chinese
 *   ideographs, incl. every zh item name, plus the Japanese locale kanji/kana)
 *   — ~839 KiB (858,784 B)
 * - Noto Sans JP: Japanese letterforms (5.0) — ja text and every ja item name
 *   only — ~470 KiB (481,556 B)
 * - Noto Sans KR: Hangul syllables (incl. every ko item name) + ASCII — the
 *   only face with Hangul — ~201 KiB (206,300 B)
 *
 * WHICH FACE DRAWS A CJK GLYPH. Every card text stack is Latin-led (`Onest,
 * Noto Sans JP, Noto Sans SC, Noto Sans KR`, and the Space Grotesk / Fragment
 * Mono variants), so the primary face draws what it has, and resvg fills every
 * other glyph from the loaded faces in the order `getFontBuffers()` returns
 * them — not the order the font-family list names them. That load order is
 * JP, SC, KR for ja, so a kanji both JP and SC carry draws in its Japanese
 * form; and SC, KR, JP for every other locale, so zh keeps SC's Chinese forms
 * and JP draws only what SC and KR both lack. Until 2026-10-06 every locale
 * loaded SC first, so ja text drew every kanji SC carries from SC — in its
 * Chinese form wherever the two designs differ (骨 直 角 写 …; most shared
 * glyphs are identical). font-load-order.test.ts renders both orders.
 *
 * The three subsets total ~1.48 MiB raw / ~0.9 MiB gzipped; the binding limit
 * is Cloudflare's 3 MiB *gzipped* Worker size (`pnpm run check-bundle-size`
 * reports the real figure: 2,717.2 KiB after the ja item names joined).
 */

// Static font imports - wrangler bundles these as ArrayBuffer at build time.
//
// The brand faces ship as STATIC instances (Regular / SemiBold / Bold), never
// the variable files: resvg's font database cannot move a variable axis, so a
// variable file exposes only its default instance and every `font-weight` the
// cards asked for rendered at that one weight (Space Grotesk's default is
// Light 300 — every title shipped thin until 2026-08-29). Regenerate with
// scripts/instance-latin-fonts.py (sources in scripts/font-sources/);
// font-faces.test.ts renders 400 / 600 / 700 and fails if any two match.
// @ts-expect-error - Binary imports are handled by wrangler bundler
import spaceGroteskRegular from '../fonts/SpaceGrotesk-Regular.ttf';
// @ts-expect-error - Binary imports are handled by wrangler bundler
import spaceGroteskSemiBold from '../fonts/SpaceGrotesk-SemiBold.ttf';
// @ts-expect-error - Binary imports are handled by wrangler bundler
import spaceGroteskBold from '../fonts/SpaceGrotesk-Bold.ttf';
// @ts-expect-error - Binary imports are handled by wrangler bundler
import onestRegular from '../fonts/Onest-Regular.ttf';
// @ts-expect-error - Binary imports are handled by wrangler bundler
import onestSemiBold from '../fonts/Onest-SemiBold.ttf';
// @ts-expect-error - Binary imports are handled by wrangler bundler
import onestBold from '../fonts/Onest-Bold.ttf';
// @ts-expect-error - Binary imports are handled by wrangler bundler
import fragmentMonoData from '../fonts/FragmentMono-Regular.ttf';

// CJK font imports - subsetted via apps/discord-worker/scripts/subset-cjk-fonts.py
// Noto Sans SC: Chinese ideographs + Japanese kanji/kana (~839 KiB)
// @ts-expect-error - Binary imports are handled by wrangler bundler
import notoSansCjkData from '../fonts/NotoSansSC-Subset.ttf';
// Noto Sans KR: Korean Hangul syllables
// @ts-expect-error - Binary imports are handled by wrangler bundler
import notoSansKrData from '../fonts/NotoSansKR-Subset.ttf';
// Noto Sans JP: Japanese kana + kanji in Japanese letterforms (5.0). It draws
// them only where it loads ahead of SC — for ja (see the header).
// @ts-expect-error - Binary imports are handled by wrangler bundler
import notoSansJpData from '../fonts/NotoSansJP-Subset.ttf';
// Type-only, so erased: this module still has no runtime import beyond the fonts.
import type { LocaleCode } from '@xivdyetools/types';

/** Each face's bytes as a Uint8Array, built once: both load orders share them. */
let faces: { latin: Uint8Array[]; sc?: Uint8Array; kr?: Uint8Array; jp?: Uint8Array } | null = null;
/** The two load orders, each cached on first use. */
let scFirstCache: Uint8Array[] | null = null;
let jpFirstCache: Uint8Array[] | null = null;

function loadFaces(): NonNullable<typeof faces> {
  faces ??= {
    latin: [
      new Uint8Array(spaceGroteskRegular as ArrayBuffer),
      new Uint8Array(spaceGroteskSemiBold as ArrayBuffer),
      new Uint8Array(spaceGroteskBold as ArrayBuffer),
      new Uint8Array(onestRegular as ArrayBuffer),
      new Uint8Array(onestSemiBold as ArrayBuffer),
      new Uint8Array(onestBold as ArrayBuffer),
      new Uint8Array(fragmentMonoData as ArrayBuffer),
    ],
    // CJK fonts, where available
    sc: notoSansCjkData ? new Uint8Array(notoSansCjkData as ArrayBuffer) : undefined,
    kr: notoSansKrData ? new Uint8Array(notoSansKrData as ArrayBuffer) : undefined,
    jp: notoSansJpData ? new Uint8Array(notoSansJpData as ArrayBuffer) : undefined,
  };
  return faces;
}

/**
 * Returns font file data as Uint8Array buffers for resvg-wasm, in the order
 * resvg falls back through them: the Latin brand faces, then the CJK subsets
 * JP, SC, KR for `ja` and SC, KR, JP for every other locale (or none). That
 * order, not a card's font-family list, decides which face draws a CJK glyph
 * the primary face lacks — see the header. Both orders are cached after first
 * use and share the same buffers.
 *
 * Usage with resvg:
 * ```typescript
 * const resvg = new Resvg(svgString, {
 *   font: {
 *     fontBuffers: getFontBuffers(locale),
 *     defaultFontFamily: 'Onest',
 *   },
 * });
 * ```
 *
 * @param locale - the locale the card is drawn in (a bot locale code)
 */
export function getFontBuffers(locale?: LocaleCode): Uint8Array[] {
  if (locale === 'ja') {
    if (!jpFirstCache) {
      const { latin, sc, kr, jp } = loadFaces();
      jpFirstCache = [...latin, ...[jp, sc, kr].filter((f): f is Uint8Array => f !== undefined)];
    }
    return jpFirstCache;
  }
  if (!scFirstCache) {
    const { latin, sc, kr, jp } = loadFaces();
    scFirstCache = [...latin, ...[sc, kr, jp].filter((f): f is Uint8Array => f !== undefined)];
  }
  return scFirstCache;
}
